#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long q;
    cin >> q;
    vector<string> ns(q);
    for (int i = 0; i < q; i++) cin >> ns[i];
    vector<long long> ks(q);
    for (int i = 0; i < q; i++) cin >> ks[i];

    for (long long index = 0; index < q; index++) {
        const string& N = ns[index];
        int kk = (int)ks[index];
        vector<long long> freeCount(kk, 0), next(kk, 0);
        int tight = 0;
        for (char ch : N) {
            int d = ch - '0';
            fill(next.begin(), next.end(), 0);
            for (int r = 0; r < kk; r++) {
                if (freeCount[r] == 0) continue;
                for (int x = 0; x < 10; x++) next[(r + x) % kk] += freeCount[r];
            }
            for (int x = 0; x < d; x++) next[(tight + x) % kk] += 1;
            freeCount = next;
            tight = (tight + d) % kk;
        }
        cout << freeCount[0] + (tight == 0 ? 1 : 0) - 1 << "\n";
    }

    return 0;
}

