import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long q = Long.parseLong(next());
        String[] ns = new String[(int) q];
        for (int i = 0; i < ns.length; i++) ns[i] = next();
        long[] ks = new long[(int) q];
        for (int i = 0; i < ks.length; i++) ks[i] = Long.parseLong(next());

        StringBuilder out = new StringBuilder();
        for (int index = 0; index < q; index++) {
            String number = ns[index];
            int kk = (int) ks[index];
            long[] freeCount = new long[kk];
            long[] next = new long[kk];
            int tight = 0;
            for (int p = 0; p < number.length(); p++) {
                int d = number.charAt(p) - '0';
                Arrays.fill(next, 0);
                for (int r = 0; r < kk; r++) {
                    if (freeCount[r] == 0) continue;
                    for (int x = 0; x < 10; x++) next[(r + x) % kk] += freeCount[r];
                }
                for (int x = 0; x < d; x++) next[(tight + x) % kk] += 1;
                long[] swap = freeCount;
                freeCount = next;
                next = swap;
                tight = (tight + d) % kk;
            }
            out.append(freeCount[0] + (tight == 0 ? 1 : 0) - 1).append("\n");
        }
        System.out.print(out);
    }
}
